import { mkdir, writeFile, readdir, stat } from 'node:fs/promises';
import { join } from 'node:path';

const root = join(import.meta.dirname, 'reports');
await mkdir(join(root, '2026'), { recursive: true });
await writeFile(join(root, 'summary.txt'), 'Three reports this year\n');
await writeFile(join(root, '2026', 'november.txt'), 'Sales were up\n');

const entries = await readdir(root, { withFileTypes: true });
entries.sort((a, b) => a.name.localeCompare(b.name));

for (const entry of entries) {
  if (entry.isDirectory()) {
    console.log(`[dir]  ${entry.name}`);
  } else {
    const info = await stat(join(root, entry.name));
    console.log(`[file] ${entry.name} (${info.size} bytes)`);
  }
}

import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const file = join(import.meta.dirname, 'notes.json');

async function loadNotes() {
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

const notes = await loadNotes();
notes.push({ id: notes.length + 1, text: process.argv[2] ?? 'Untitled note' });
await writeFile(file, JSON.stringify(notes, null, 2) + '\n');
console.log(`Saved ${notes.length} note(s) to notes.json`);
